typedef float rational_t;

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;
};

class vector4d
{
public:
  typedef rational_t T;
  T x,y,z,w;
};

class matrix4x4
{
public:
  typedef rational_t T;
  typedef vector4d row;

  row x __attribute__((aligned(16)));
  row y;
  row z;
  row w;

  void make_rotate( const vector3d& u, T a );
};

void fast_sin_cos_approx( float rads, float* sinx, float* cosx );

void matrix4x4::make_rotate( const vector3d& u, rational_t a )
{
  rational_t sa, ca;

  fast_sin_cos_approx( a, &sa, &ca );

  x.x = u.x * u.x + ca * (1.0f - u.x * u.x);
  y.x = u.x * u.y * (1.0f - ca) - u.z * sa;
  z.x = u.x * u.z * (1.0f - ca) + u.y * sa;
  w.x = 0.0f;
  x.y = u.x * u.y * (1.0f - ca) + u.z * sa;
  y.y = u.y * u.y + ca * (1.0f - u.y * u.y);
  z.y = u.y * u.z * (1.0f - ca) - u.x * sa;
  w.y = 0.0f;
  x.z = u.x * u.z * (1.0f - ca) - u.y * sa;
  y.z = u.y * u.z * (1.0f - ca) + u.x * sa;
  z.z = u.z * u.z + ca * (1.0f - u.z * u.z);
  w.z = 0.0f;
  x.w = 0.0f;
  y.w = 0.0f;
  z.w = 0.0f;
  w.w = 1.0f;
}
